    de: "Der zurueckgegebene Scan-Typ passt nicht zur angeforderten Route.",
    it: "Il tipo di scansione restituito non corrisponde al percorso richiesto.",
    es: "El tipo de escaneo devuelto no coincide con la ruta solicitada.",
    pt: "O tipo de escaneamento retornado nao corresponde a rota solicitada.",
  },
};

function getLocalizedMessage(key) {
  const table = LOCALIZED_MESSAGES[key] ?? LOCALIZED_MESSAGES.generic_analysis_error;
  return table[languageCode] ?? table.en ?? "Unknown error.";
}

function stripCodeFences(value) {
  if (typeof value !== "string") return "";
  const trimmed = value.trim();
  if (!trimmed) return "";
  const fence = String.fromCharCode(96).repeat(3);
  return trimmed
    .replace(new RegExp(fence + "(?:json)?\\s*([\\s\\S]*?)\\s*" + fence, "gi"), "$1")
    .trim();
}

function parseScalarNumber(value) {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : null;
  }
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  if (!trimmed) return null;
  const parsed = Number(trimmed);
  return Number.isFinite(parsed) ? parsed : null;
}

function clampNumber(value, min, max) {
  const parsed = parseScalarNumber(value);
  if (parsed === null) return null;
  return Math.min(Math.max(parsed, min), max);
}

function normalizeEnumKey(value, allowed) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim().toLowerCase();
  if (!trimmed) return null;
  return allowed.includes(trimmed) ? trimmed : null;
}

function normalizeEnumArray(value, allowed) {
  if (!Array.isArray(value)) return [];
  const seen = new Set();
  const result = [];
  for (const item of value) {
    const normalized = normalizeEnumKey(item, allowed);
    if (normalized && !seen.has(normalized)) {
      seen.add(normalized);
      result.push(normalized);
    }
  }
  return result;
}

function pickFirstValue(values) {
  for (const value of values) {
    if (value !== undefined && value !== null) {
      return value;
    }
  }
  return null;
}

function normalizeContractToken(value) {
  const text = readText(value);
  if (!text) return null;
  return text
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/['’]+/g, "")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function resolveCatalogKey(value, allowedKeys, aliases, fallbackKey) {
  const token = normalizeContractToken(value);
  if (!token) return fallbackKey;
  if (allowedKeys.has(token)) return token;
  return aliases[token] ?? fallbackKey;
}

function readTextArray(value) {
  if (!Array.isArray(value)) return [];

  return value
    .map((item) => {
      if (typeof item === "string") {
        return readText(item);
      }

      if (isPlainObject(item)) {
        return readText(
          pickFirstValue([
            item.label,
            item.name,
            item.value,
            item.text,
            item.title,
            item.key,
          ]),
        );
      }

      return null;
    })
    .filter(Boolean);
}

function joinTextArray(value) {
  const entries = readTextArray(value);
  return entries.length > 0 ? entries.join(", ") : null;
}

function splitVitaminText(value) {
  const text = readText(value);
  if (!text) return [];

  return text
    .split(/[,;/&+]+|\bet\b|\band\b|\bund\b|\by\b|\be\b/gi)
    .map((item) => readText(item))
    .filter(Boolean);
}

function normalizeFaceShapeKey(value) {
  return resolveCatalogKey(value, allowedFaceShapeKeys, faceShapeAliases, "unknown");
}

function normalizeBodyTypeKey(value) {
  return resolveCatalogKey(value, allowedBodyTypeKeys, bodyTypeAliases, "unknown");
}

function normalizeMuscleMassKey(value) {
  return resolveCatalogKey(value, allowedMuscleMassKeys, muscleMassAliases, "unknown");
}

function normalizeIngredientQualityKey(value) {
  return resolveCatalogKey(
    value,
    allowedIngredientQualityKeys,
    ingredientQualityAliases,
    "unknown",
  );
}

function normalizeGlycemicIndexKey(value) {
  return resolveCatalogKey(value, allowedGlycemicIndexKeys, glycemicIndexAliases, "unknown");
}

function normalizeNutritionVitaminKey(value) {
  const token = normalizeContractToken(value);
  if (!token) return null;
  if (allowedNutritionVitaminKeys.has(token)) return token;
  if (nutritionVitaminAliases[token]) return nutritionVitaminAliases[token];

  const withoutPrefix = token.replace(/^(vitamins?|vitamine?s?|vitamina?s?)_?/, "");
  if (withoutPrefix && withoutPrefix !== token) {
    if (allowedNutritionVitaminKeys.has(withoutPrefix)) return withoutPrefix;
    if (nutritionVitaminAliases[withoutPrefix]) return nutritionVitaminAliases[withoutPrefix];
    const canonicalVitaminKey = `vitamin_${withoutPrefix}`;
    if (allowedNutritionVitaminKeys.has(canonicalVitaminKey)) return canonicalVitaminKey;
  }

  return null;
}

function normalizeNutritionVitaminKeys(value) {
  const candidates = [];

  if (Array.isArray(value)) {
    candidates.push(...readTextArray(value));
  } else {
    const directText = readText(value);
    if (directText) {
      candidates.push(directText);
    }
  }

  const keys = [];
  const seen = new Set();

  for (const candidate of candidates) {
    const parts = splitVitaminText(candidate);
    const tokens = parts.length > 0 ? parts : [candidate];

    for (const token of tokens) {
      const normalizedKey = normalizeNutritionVitaminKey(token);
      if (normalizedKey && normalizedKey !== "unknown" && !seen.has(normalizedKey)) {
        seen.add(normalizedKey);
        keys.push(normalizedKey);
      }
    }
  }

  if (keys.length > 0) {
    return keys;
  }

  return candidates.length > 0 ? ["unknown"] : [];
}

function normalizeNutritionVerdictKey(value) {
  const token = normalizeContractToken(value);
  if (!token) return null;
  if (allowedNutritionVerdictKeys.has(token)) return token;
  return nutritionVerdictAliases[token] ?? null;
}

function isFiniteNumberValue(value) {
  return typeof value === "number" && Number.isFinite(value);
}

function deriveNutritionVerdictKey(source) {
  const explicitKey = normalizeNutritionVerdictKey(source.verdict_key ?? source.verdictKey);
  if (explicitKey) return explicitKey;

  const textKey = normalizeNutritionVerdictKey(source.short_verdict ?? source.verdict ?? source.verdict_label);
  if (textKey) return textKey;

  const plateScore = clampNumber(source.plate_health_score, 0, 100);
  const calories = clampNumber(source.calories_estimate, 0, 10000);
  const protein = clampNumber(source.protein_grams, 0, 1000);
  const fat = clampNumber(source.fat_grams, 0, 1000);
  const sugar = clampNumber(source.sugar_grams_estimate, 0, 300);
  const processing = clampNumber(source.processing_level_score, 0, 100);
  const mealBalance = clampNumber(source.meal_balance_score, 0, 100);
  const proteinVisibility = clampNumber(source.protein_visibility_score, 0, 100);
  const sodiumLevel = clampNumber(source.sodium_level_score, 0, 10);
  const ingredientQualityToken = normalizeContractToken(
    pickFirstValue([
      source.ingredient_quality_key,
      source.ingredientQualityKey,
      source.ingredient_quality,
      source.ingredient_quality_label,
    ]),
  );
  const mealType = normalizeEnumKey(source.meal_type_key, ["breakfast", "lunch", "dinner", "snack", "dessert", "other"]);

  if (
    (isFiniteNumberValue(processing) && processing >= 65) ||
    ingredientQualityToken === "processed" ||
    ingredientQualityToken === "ultra_processed" ||
    ingredientQualityToken === "transforme" ||
    ingredientQualityToken === "transformee"
  ) {
    return "processed";
  }

  if (
    (isFiniteNumberValue(sugar) && sugar >= 30) ||
    (mealType === "dessert" && (!isFiniteNumberValue(sugar) || sugar >= 18))
  ) {
    return "sugary";
  }

  if (
    (isFiniteNumberValue(protein) && protein >= 25) ||
    (isFiniteNumberValue(proteinVisibility) && proteinVisibility >= 70)
  ) {
    return "protein_dense";
  }

  if (
    (isFiniteNumberValue(calories) && calories <= 350 && (!isFiniteNumberValue(plateScore) || plateScore >= 55)) ||
    normalizeEnumKey(source.portion_size_key, ["small", "medium", "large", "oversized"]) === "small"
  ) {
    return "light";
  }

  if (
    (isFiniteNumberValue(calories) && calories >= 850) ||
    (isFiniteNumberValue(fat) && fat >= 35) ||
    (isFiniteNumberValue(sodiumLevel) && sodiumLevel >= 8)
  ) {
    return "indulgent";
  }

  if (
    (isFiniteNumberValue(mealBalance) && mealBalance >= 60) ||
    (isFiniteNumberValue(plateScore) && plateScore >= 60)
  ) {
    return "balanced";
  }

  return "balanced";
}

