function scanTextForParsedObjects(text) {
  const results = [];
  for (let start = 0; start < text.length; start += 1) {
    if (text[start] !== "{") continue;

    let depth = 0;
    let inString = false;
    let escaped = false;

    for (let index = start; index < text.length; index += 1) {
      const char = text[index];

      if (inString) {
        if (escaped) {
          escaped = false;
        } else if (char === "\\") {
          escaped = true;
        } else if (char === "\"") {
          inString = false;
        }
        continue;
      }

      if (char === "\"") {
        inString = true;
        continue;
      }

      if (char === "{") {
        depth += 1;
      } else if (char === "}") {
        depth -= 1;
        if (depth === 0) {
          const candidate = text.slice(start, index + 1);
          try {
            results.push(JSON.parse(candidate));
          } catch {}
          break;
        }
      }
    }
  }
  return results;
}

const nestedCandidateKeys = ["data", "message", "content", "parts", "output", "text", "response", "result", "payload"];

function collectObjectsFromValue(value, depth) {
  if (depth > 6 || value === null || value === undefined) {
    return [];
  }

  if (typeof value === "string") {
    return collectObjectsFromString(value, depth + 1);
  }

  if (Array.isArray(value)) {
    const nested = [];
    for (const entry of value) {
      nested.push(...collectObjectsFromValue(entry, depth + 1));
    }
    return nested;
  }

  if (!isPlainObject(value)) {
    return [];
  }

  const results = [value];

  for (const key of nestedCandidateKeys) {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      results.push(...collectObjectsFromValue(value[key], depth + 1));
    }
  }

  if (Array.isArray(value.choices)) {
    results.push(...collectObjectsFromValue(value.choices, depth + 1));
  }

  return results;
}

function collectObjectsFromString(value, depth) {
  if (depth > 6) return [];

  const stripped = stripCodeFences(value);
  if (!stripped) return [];

  try {
    const parsed = JSON.parse(stripped);
    const nested = collectObjectsFromValue(parsed, depth + 1);
    if (nested.length > 0) {
      return nested;
    }
  } catch {}

  const extracted = [];
  for (const parsedCandidate of scanTextForParsedObjects(stripped)) {
    extracted.push(...collectObjectsFromValue(parsedCandidate, depth + 1));
  }
  return extracted;
}

function appearsToBeScanJson(text) {
  return /"(?:scan_type|schema_version|analysis_meta)"\s*:/.test(text);
}

function isLikelyTruncatedJsonText(value) {
  const stripped = stripCodeFences(value);
  if (!stripped || !stripped.includes("{") || !appearsToBeScanJson(stripped)) {
    return false;
  }

  let depth = 0;
  let inString = false;
  let escaped = false;
  let sawObject = false;

  for (const char of stripped) {
    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === "\"") {
        inString = false;
      }
      continue;
    }

    if (char === "\"") {
      inString = true;
      continue;
    }

    if (char === "{") {
      depth += 1;
      sawObject = true;
    } else if (char === "}") {
      depth = Math.max(0, depth - 1);
    }
  }

  return sawObject && (depth > 0 || inString);
}

function hasLikelyTruncatedJson(value, depth) {
  if (depth > 6 || value === null || value === undefined) {
    return false;
  }

  if (typeof value === "string") {
    return isLikelyTruncatedJsonText(value);
  }

  if (Array.isArray(value)) {
    return value.some((entry) => hasLikelyTruncatedJson(entry, depth + 1));
  }

  if (!isPlainObject(value)) {
    return false;
  }

  for (const key of nestedCandidateKeys) {
    if (Object.prototype.hasOwnProperty.call(value, key) && hasLikelyTruncatedJson(value[key], depth + 1)) {
      return true;
    }
  }

  return Array.isArray(value.choices) && hasLikelyTruncatedJson(value.choices, depth + 1);
}

