function wrapResult(data, explicitError) {
  const isError = data.scan_type === "error";
  const resolvedError = isError
    ? readText(explicitError) || readText(data.message) || getLocalizedMessage("generic_analysis_error")
    : null;

  return [
    {
      json: {
        success: !isError,
        ...(isError ? { error: resolvedError } : {}),
        data: isError
          ? {
              ...data,
              message: resolvedError,
            }
          : data,
      },
    },
  ];
}

function errorResult(messageKey, explicitMessage) {
  const message = readText(explicitMessage) || getLocalizedMessage(messageKey);
  return wrapResult({
    scan_type: "error",
    message,
  }, message);
}

